        print(f'{k}: {ops[k]}')
    else:
        print(f'{k}: NOT FOUND')

# Also check some other useful keys
for k in sorted(ops.keys()):
    if any(x in k.lower() for x in ['base', 'neuro', 'tau', 'fs', 'nframe', 'frame']):
        print(f'  {k}: {ops[k] if not isinstance(ops[k], np.ndarray) else ops[k].shape}')
"

